NEWF = json.loads(r"""{"inc/dejavoo-pay.php": "<?php\n/* (2.99.638c - LENH-638 A) Checkout -> Card -> \"Card on the P5\": the card part is sent to the Dejavoo P5 FIRST; the receipt is saved only after the P5 approved.\n   One P5 payment per ticket (key = its appointment ids): tapping twice, a lost answer, or saving the receipt again after an error NEVER charges again \u2013\n   the approved payment waits (setting dv_pend) until checkout_save uses it (same DB transaction as the receipt). A payment approved but not used\n   (the desk changed the ticket / closed Checkout) stays in the list -> \"Cancel on the P5\" (Void) \u2013 never lost: dv_log + 638e close-day check.\n   Only when dv_on = 1 and the P5 is set up; otherwise Checkout is exactly as before. */\ndeclare(strict_types=1);\nrequire_once __DIR__ . '/dejavoo.php';\n\nconst DV_PEND_KEEP = 200;\nfunction dv_pend(): array { $p = json_decode((string)setting('dv_pend'), true); return is_array($p) ? $p : []; }\nfunction dv_pend_put(string $ref, array $row): void {\n    $p = dv_pend(); $p[$ref] = $row + ($p[$ref] ?? []);\n    if (count($p) > DV_PEND_KEEP) { uasort($p, fn($a, $b) => strcmp((string)($a['at'] ?? ''), (string)($b['at'] ?? ''))); while (count($p) > DV_PEND_KEEP) { $k = array_key_first($p); if (in_array($p[$k]['st'] ?? '', ['paid', 'wait'], true)) break; unset($p[$k]); } }\n    set_setting('dv_pend', json_encode($p, JSON_UNESCAPED_UNICODE));\n}\n/** The ticket = its appointments (sorted ids). */\nfunction dv_key(array $ids): string { $i = array_values(array_unique(array_filter(array_map('intval', $ids)))); sort($i); return $i ? 'T' . implode('-', $i) : ''; }\nfunction dv_pay_on(): bool { return dv_on() && dv_ready(); }\nfunction dv_card_out(string $ref, array $r): array {\n    return ['ref' => $ref, 'amt' => (float)$r['amt'], 'last4' => (string)($r['last4'] ?? ''), 'card' => (string)($r['card'] ?? ''), 'auth_code' => (string)($r['auth_code'] ?? '')];\n}\n/** The desk taps Pay with \"Card on the P5\": charge $amt for this ticket (or give back the payment already approved for it). Returns the card, or fails with why. */\nfunction dv_charge(array $ids, float $amt): array {\n    if (!dv_pay_on()) fail('Card on the P5 is off (Settings \u2192 Payments).', 400);\n    $key = dv_key($ids); $amt = round($amt, 2); if ($key === '' || $amt < 0.01 || $amt > 20000) fail('Check the amount.');\n    app_lock('dejavoo'); // one P5: a 2nd tap waits here, then finds the 1st payment\n    foreach (dv_pend() as $ref => $r) {\n        if (($r['key'] ?? '') !== $key) continue;\n        if (($r['st'] ?? '') === 'wait') { // a request that never finished (closed tab, server restart): ask the P5 first\n            $s = dv_status((string)$ref);\n            if ($s['status'] === 'approved') { $r = ['st' => 'paid', 'amt' => (float)($s['total'] ?? $r['amt']), 'last4' => $s['last4'] ?? '', 'card' => $s['card'] ?? '', 'auth_code' => $s['auth_code'] ?? '', 'pnref' => $s['pnref'] ?? ''] + $r; dv_pend_put((string)$ref, $r); }\n            elseif ($s['status'] === 'not_found') { dv_pend_put((string)$ref, ['st' => 'failed']); continue; }\n            else fail('The P5 may still be busy with this ticket \u2013 look at the P5 before trying again.', 409);\n        }\n        if (($r['st'] ?? '') === 'paid') {\n            if (abs((float)$r['amt'] - $amt) < 0.005) return dv_card_out((string)$ref, $r) + ['again' => true];\n            json_out(['error' => 'The P5 already took ' . usd((float)$r['amt']) . ' for this ticket (not ' . usd($amt) . '). Cancel it on the P5 first, or pay ' . usd((float)$r['amt']) . '.',\n                'dvPaid' => dv_card_out((string)$ref, $r)], 409);\n        }\n    }\n    $ref = dv_new_ref(); dv_pend_put($ref, ['key' => $key, 'amt' => $amt, 'st' => 'wait', 'at' => now_str(), 'by' => actor_name()]);\n    if (session_status() === PHP_SESSION_ACTIVE) @session_write_close(); // up to 2 minutes on the P5: the other screens keep working\n    $wait = max(1, min(DV_WAIT, (int)(cfg()['dv_wait'] ?? DV_WAIT))); // the test kit: a short wait (config only)\n    ignore_user_abort(true); @set_time_limit($wait + 60);\n    $s = dv_sale($amt, 0, $ref, $key, $wait);\n    if (!empty($s['paid'])) {\n        $tot = isset($s['total']) && $s['total'] !== null ? round((float)$s['total'], 2) : $amt;\n        $row = ['st' => 'paid', 'amt' => $tot, 'last4' => (string)($s['last4'] ?? ''), 'card' => (string)($s['card'] ?? ''), 'auth_code' => (string)($s['auth_code'] ?? ''), 'pnref' => (string)($s['pnref'] ?? ''), 'paid_at' => now_str()];\n        dv_pend_put($ref, $row);\n        audit('dejavoo', 'P5 card ' . usd($tot), '', 'approved \u00b7 ' . ($row['card'] ?: 'card') . ($row['last4'] !== '' ? ' \u00b7\u00b7' . $row['last4'] : '') . ' \u00b7 auth ' . $row['auth_code'] . ' \u00b7 ref ' . $ref . ' \u00b7 ' . $key);\n        if (abs($tot - $amt) >= 0.005) json_out(['error' => 'The P5 took ' . usd($tot) . ', the ticket says ' . usd($amt) . '. Check the P5 (cancel it there if it is wrong).', 'dvPaid' => dv_card_out($ref, $row + ['amt' => $tot])], 409);\n        return dv_card_out($ref, $row);\n    }\n    dv_pend_put($ref, ['st' => !empty($s['unsure']) ? 'unsure' : 'failed', 'why' => $s['status']]);\n    $why = ['declined' => 'Card declined.', 'cancelled' => 'Cancelled on the P5.', 'not_connected' => 'The P5 is not connected (turn it on / check its internet).', 'auth' => 'The P5 is not set up right (NailFlow).',\n        'partial' => 'The P5 approved only PART of it \u2013 cancel it on the P5, then try again.'][$s['status']] ?? ('The P5 did not answer' . ($s['msg'] ? ' (' . $s['msg'] . ')' : '') . '.');\n    if (!empty($s['unsure']) || empty($s['retry_ok'])) $why .= ' Not sure the card was charged \u2013 look at the P5 (its last transaction) before trying again.';\n    fail($why, 402);\n}\n/** checkout_save: a Card part paid on the P5. The approved payment of THIS ticket with THIS amount, not used yet -> its card details; else it stops. */\nfunction dv_take(string $ref, array $ids, float $amt): array {\n    $r = dv_pend()[$ref] ?? null;\n    if (!$r || ($r['st'] ?? '') !== 'paid') fail('The P5 payment was not approved (or was used already) \u2013 tap Pay again.', 409);\n    if (($r['key'] ?? '') !== dv_key($ids)) fail('That P5 payment is for another ticket.', 409);\n    if (abs((float)$r['amt'] - round($amt, 2)) >= 0.005) fail('The card part (' . usd($amt) . ') is not what the P5 took (' . usd((float)$r['amt']) . ').', 409);\n    return $r;\n}\nfunction dv_used(string $ref, int $rno): void { dv_pend_put($ref, ['st' => 'used', 'rno' => $rno, 'used_at' => now_str()]); }\n/** \"Cancel on the P5\" for a payment approved but not on a receipt (Void, before the batch closes). */\nfunction dv_cancel(string $ref): array {\n    app_lock('dejavoo');\n    $r = dv_pend()[$ref] ?? null; if (!$r || ($r['st'] ?? '') !== 'paid') fail('Nothing to cancel (no P5 payment waiting).', 404);\n    $v = dv_void((float)$r['amt'], $ref);\n    if (empty($v['ok'])) fail('The P5 did not cancel it (' . ($v['msg'] ?: $v['status']) . '). Do it on the P5 (Void) \u2013 the ticket is not changed.', 409);\n    dv_pend_put($ref, ['st' => 'void', 'void_at' => now_str()]);\n    audit('dejavoo', 'P5 card ' . usd((float)$r['amt']), 'approved', 'cancelled on the P5 (void) \u00b7 ref ' . $ref . ' \u00b7 ' . ($r['key'] ?? ''));\n    return ['ok' => true];\n}\n/** Approved on the P5 but not on a receipt yet (for the desk / close day). */\nfunction dv_waiting(): array { $o = []; foreach (dv_pend() as $ref => $r) if (($r['st'] ?? '') === 'paid') $o[] = dv_card_out((string)$ref, $r) + ['key' => (string)($r['key'] ?? ''), 'at' => (string)($r['paid_at'] ?? $r['at'] ?? '')]; return $o; }\n", "inc/api/dvpay.php": "<?php\n/* (2.99.638c - LENH-638 A) Checkout (owner / manager / front desk iPad): the card part on the Dejavoo P5 \u2013 inc/dejavoo-pay.php. Off = these say so. */\ndeclare(strict_types=1);\nif (!defined('API_MAIN')) { http_response_code(404); exit; }\nrequire_once APP_ROOT . '/inc/dejavoo-pay.php';\nneed_desk();\nswitch ($action) {\ncase 'dv_charge':\n    if ($method !== 'POST') fail('POST only', 405);\n    desk_out(['ok' => true] + dv_charge((array)($in['ids'] ?? []), (float)($in['amt'] ?? 0)));\ncase 'dv_cancel':\n    if ($method !== 'POST') fail('POST only', 405);\n    desk_out(dv_cancel((string)($in['ref'] ?? '')));\ncase 'dv_waiting':\n    desk_out(['on' => dv_pay_on(), 'waiting' => dv_waiting()]);\n}\nfail('Unknown action', 404);\n"}""")
